"""TP-M7-14 G55 PostgreSQL half (TASK-154): 500 generated files through the
pipeline never leave a partial import. CHK-M7-197; REQ-176 (2); TS §8.3
"Property/fuzz ... no partial import"; SR §3.6 (roll back the whole file on
any error); #98 (j) (an internal error writes no row). Mutation row
CHK-M7-340 (a late exception swallowed and the transaction committed).

The files are generated by a seeded ``random.Random`` (reproducible, exactly
500, and the outcome mix is asserted at the end) rather than by Hypothesis,
whose example count and shrinking do not fit one long stateful database run.
Each file is a structured mutation (names and plugin ids drawn from small
pools, so updates, retires, BIT005, BIT007 and BIT015 happen), optionally a
byte-level mutation on top, and in about one case in eight an injected fault
(an ``OSError`` from ``before_commit``, or a real database error in the
middle of the store). After each file: if it was rejected, skipped, refused
or failed, every catalog checksum equals the one before; if it succeeded,
the policy is exactly the file (name, status, hash, plugins in order with
their commands, all active and owned by it). Owner: tester-m7-154.
"""

from __future__ import annotations

import random
from collections import Counter
from collections.abc import Iterator
from pathlib import Path
from typing import Any
from uuid import UUID, uuid4

import psycopg
import pytest
from pydantic import SecretStr

from bitscan_manager.db.pool import AppDatabase
from bitscan_manager.repositories import catalog_plugins
from bitscan_manager.repositories.catalog_lock import catalog_lock
from bitscan_manager.services.importer import store
from bitscan_manager.services.importer.pipeline import (
    Actor,
    FileInput,
    Mode,
    import_one,
    prepare,
)

from .catalog_rows import owner
from .conftest import PgServer, own_migrated_server
from .pipeline_rows import (
    ALL,
    NONE,
    FixedClock,
    P,
    bit,
    bits_dir,
    catalog_now,
    imports_since,
    server_file,
    sha,
    snap,
    upload_file,
)

pytestmark = pytest.mark.pg

FILES = 500
SYSTEM = Actor("system", None)
NAMES = [f"Fuzz policy {i}" for i in range(12)]
PATHS = [f"fuzz-{i}.bit" for i in range(12)]
EXECUTES = [
    "cat /etc/hostname",
    "dpkg-query -W -f='${Status}' apparmor 2>/dev/null",
    "grep -E '^\\s*PermitRootLogin' /etc/ssh/sshd_config",
    "stat -c %a /etc/passwd",
    "systemctl is-enabled ssh",
    "rm -f /etc/issue",  # BIT102
    "echo x > /etc/motd",  # BIT102
    "",  # BIT008
]
STATUSES = ["enabled", "disabled", "Enabled", "on"]
SPLICE = [b"<", b">", b"</Plugin>", b"&", b"<!DOCTYPE x>", b"\x00", b"]]>", b"\xff"]


@pytest.fixture(scope="module")
def server(tmp_path_factory: pytest.TempPathFactory) -> Iterator[PgServer]:
    with own_migrated_server(tmp_path_factory.mktemp("fuzz")) as s:
        yield s


@pytest.fixture(scope="module")
def db(server: PgServer) -> Iterator[AppDatabase]:
    d = AppDatabase(
        SecretStr(server.dsn("bitscan_app")), max_size=2, connect_timeout_s=3
    )
    d.open()
    try:
        yield d
    finally:
        d.close()


GOOD = EXECUTES[:5]
BAD = EXECUTES[5:]


def generate(
    rng: random.Random, pools: list[list[UUID]], shared: list[UUID]
) -> tuple[int, bytes]:
    """(name index, file). Each name has its own plugin-id pool; a few ids
    are shared, so BIT015 and BIT005 happen without drowning the successes."""
    n = rng.randrange(len(NAMES))
    plugins = []
    for _ in range(rng.randint(1, 4)):
        r = rng.random()
        u = (
            rng.choice(shared)
            if r < 0.05
            else uuid4()
            if r < 0.2
            else rng.choice(pools[n])
        )
        execute = rng.choice(BAD) if rng.random() < 0.08 else rng.choice(GOOD)
        plugins.append(P(execute=execute, uuid=u))
    status = (
        rng.choice(STATUSES[3:]) if rng.random() < 0.08 else rng.choice(STATUSES[:3])
    )
    data, _ = bit(NAMES[n], plugins, status=status)
    if rng.random() < 0.2:  # byte-level mutation on top
        buf = bytearray(data)
        for _ in range(rng.randint(1, 4)):
            pos = rng.randrange(len(buf))
            op = rng.randrange(3)
            if op == 0:
                buf[pos] = rng.randrange(256)
            elif op == 1:
                del buf[pos : pos + rng.randint(1, 40)]
            else:
                buf[pos:pos] = rng.choice(SPLICE)
        data = bytes(buf)
    return n, data


def state_of(server: PgServer, policy_id: int) -> tuple[Any, ...]:
    with owner(server) as c:
        pol = c.execute(
            "SELECT policy_name, file_status::text, source_sha256, deleted_at"
            " FROM policy WHERE policy_id = %s",
            (policy_id,),
        ).fetchone()
        plugins = c.execute(
            "SELECT pp.plugin_uuid, p.execute, p.timeout_s, p.state::text,"
            " p.owner_policy_id FROM policy_plugin pp JOIN plugin p USING"
            " (plugin_uuid) WHERE pp.policy_id = %s ORDER BY pp.sort_order",
            (policy_id,),
        ).fetchall()
    return pol, [tuple(r) for r in plugins]


def test_500_generated_files_leave_the_catalog_complete_or_unchanged(
    server: PgServer, db: AppDatabase, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    rng = random.Random(154_500)  # noqa: S311 (reproducible test data)
    pools = [[uuid4() for _ in range(5)] for _ in NAMES]
    shared = [uuid4() for _ in range(3)]
    bits = bits_dir(tmp_path)
    fault = {"db": False}
    real_membership = catalog_plugins.replace_membership

    def membership(conn: Any, *a: Any, **k: Any) -> Any:
        out = real_membership(conn, *a, **k)
        if fault["db"]:
            conn.execute("SELECT 1/0")  # a real database error mid-store
        return out

    monkeypatch.setattr(catalog_plugins, "replace_membership", membership)

    def disk_full(policy_id: int) -> None:
        raise OSError("disk full")

    tally: Counter[str] = Counter()
    previous: FileInput | None = None
    for i in range(FILES):
        if previous is not None and rng.random() < 0.08:
            file, mode = previous, Mode.AUTO  # the same file again
        else:
            n, data = generate(rng, pools, shared)
            if rng.random() < 0.75:  # mostly the name's own file
                path = PATHS[n] if rng.random() < 0.85 else rng.choice(PATHS)
                file = server_file(data, path)
            else:
                file = upload_file(data, f"fuzz-{i}.bit")
            mode = rng.choice(list(Mode))
        previous = file
        roll = rng.random()
        fault["db"] = roll < 0.1
        before = disk_full if 0.1 <= roll < 0.2 else None
        exists = ALL if rng.random() < 0.5 else NONE
        s0 = snap(server)
        try:
            with db.session() as s, catalog_lock(s):
                out = import_one(
                    s, FixedClock(), bits, file, mode=mode, actor=SYSTEM,
                    file_exists=exists, before_commit=before,
                )  # fmt: skip
        except (OSError, psycopg.Error):
            assert before is not None or fault["db"], i
            tally["fault"] += 1
            assert catalog_now(server) == s0.catalog, i
            assert imports_since(server, s0) == [], i
            continue
        except store.PolicyManagedOnServer:
            tally["refused"] += 1
            assert catalog_now(server) == s0.catalog, i
            assert imports_since(server, s0) == [], i
            continue
        finally:
            fault["db"] = False
        tally[out.outcome] += 1
        rows = imports_since(server, s0)
        assert [r["outcome"] for r in rows] == [out.outcome], i
        if out.outcome != "success":
            assert catalog_now(server) == s0.catalog, (i, out.outcome)
            continue
        assert before is None and not fault["db"], i
        cand = prepare(file.data).candidate
        assert cand is not None and out.policy_id is not None, i
        pol, plugins = state_of(server, out.policy_id)
        assert pol == (
            cand.policy_name,
            cand.file_status,
            sha(file.data or b""),
            None,
        ), i
        assert plugins == [
            (p.plugin_uuid, p.execute, p.timeout_s, "active", out.policy_id)
            for p in cand.plugins
        ], i
    print(f"fuzz tally: {dict(tally)}")
    assert sum(tally.values()) == FILES
    # The mix must exercise every branch, or the property is empty.
    assert tally["success"] >= 50, tally
    assert tally["rejected"] >= 100, tally
    assert tally["fault"] >= 25, tally
    assert tally["skipped"] >= 1, tally
